public static MZNAG_SalesOrderBatchController construct()
{
    MZNAG_SalesOrderBatchController controller = new MZNAG_SalesOrderBatchController();
    controller.parmClassName(classStr(MZNAG_SalesOrderBatchService));
    controller.parmMethodName(methodStr(MZNAG_SalesOrderBatchService, processOperation));
    controller.parmExecutionMode(SysOperationExecutionMode::ScheduledBatch);
    return controller;
}

public static void main(Args _args)
{
    MZNAG_SalesOrderBatchController controller = MZNAG_SalesOrderBatchController::construct();
    controller.startOperation();
}
